'use strict';

/**
* Compute the inverse of a double-precision complex floating-point number.
*
* @module @stdlib/math-base-special-cinv
*
* @example
* var Complex128 = require( '@stdlib/complex-float64-ctor' );
* var cinv = require( '@stdlib/math-base-special-cinv' );
*
* var v = cinv( new Complex128( 2.0, 4.0 ) );
* // returns <Complex128>[ 0.1, -0.2 ]
*/

// MODULES //

var setReadOnly = require( '@stdlib/utils-define-nonenumerable-read-only-property' );
var main = require( './main.js' );
var assign = require( './assign.js' );
var strided = require( './strided.js' );


// MAIN //

setReadOnly( main, 'assign', assign );
setReadOnly( main, 'strided', strided );


// EXPORTS //

module.exports = main;

// exports: { "assign": "main.assign", "strided": "main.strided" }
